INSERT INTO performance_reviews (id, cycle_id, employee_id, reviewer_employee_id, overall_score, rating, strengths, improvements, summary)
VALUES
  ('d7200000-0000-4000-8000-000000000001', 'd7000000-0000-4000-8000-000000000001', 'd2000000-0000-4000-8000-000000000002', '40000000-0000-4000-8000-000000000002', 4.50, 'exceeds_expectation', '能快速抽象指标体系，跨部门沟通清晰。', '需要进一步沉淀数据口径变更记录。', '组织经营数据项目推进质量高，是本月关键贡献者。'),
