INSERT INTO knowledge_base_articles (id, company_id, category, title, question, answer, tags, is_published)
VALUES
  ('d9000000-0000-4000-8000-000000000001', '00000000-0000-0000-0000-000000000001', 'recruitment', '应聘流程状态说明', '候选人从投递到录用会经历哪些系统阶段？', '招聘系统使用新入池、筛选中、面试中、录用阶段、已录用和已淘汰六个阶段。HR 需要在每次面试、录用通知和淘汰决定后及时更新候选人状态。', '["招聘","候选人","流程"]'::jsonb, TRUE),
  ('d9000000-0000-4000-8000-000000000002', '00000000-0000-0000-0000-000000000001', 'onboarding', '新员工入职清单', '新员工入职前需要 HR、直属经理和 IT 做哪些准备？', '入职前至少完成资料收集、合同草稿、账号开通、办公设备、导师安排、试用期目标和首周培训计划。工作流待办会按照负责人拆分这些事项。', '["入职","待办","员工档案"]'::jsonb, TRUE),
  ('d9000000-0000-4000-8000-000000000003', '00000000-0000-0000-0000-000000000001', 'employee', '员工档案更新规范', '员工修改手机号、紧急联系人或银行卡信息时如何处理？', '员工可通过自助服务发起资料变更申请，HR 审核通过后再写入正式员工档案。涉及银行卡和证件信息时只保存脱敏字段。', '["员工档案","资料变更","合规"]'::jsonb, TRUE),
  ('d9000000-0000-4000-8000-000000000004', '00000000-0000-0000-0000-000000000001', 'payroll', '薪资考勤联动说明', '工资记录如何引用考勤、加班和绩效数据？', '每月生成工资记录时会参考出勤天数、已审批加班小时、绩效评分、薪资结构和扣款项。发布工资单前，HR 需要复核异常考勤和未审批加班。', '["薪资","考勤","绩效"]'::jsonb, TRUE)
ON CONFLICT (id) DO UPDATE
SET category = EXCLUDED.category,
    title = EXCLUDED.title,
    question = EXCLUDED.question,
    answer = EXCLUDED.answer,
    tags = EXCLUDED.tags,
    is_published = EXCLUDED.is_published,
    updated_at = NOW();

